window.BOOK={"key":"nabigha","app":"mutoon-nabigha","lsk":"mutoon_nabigha_v1","prefix":"na_","title":"معلقة النابغة","sub":"معلقة · النابغة الذبياني (ت نحو ١٨ ق.هـ) · ٥١ بيتًا","poems":[{"id":"nabigha","title":"معلقة النابغة","nazim":"النابغة الذبياني زياد بن معاوية","death":"ت نحو ١٨ ق.هـ","meter":"البسيط","source":"المكتبة الشاملة: شرح القصائد العشر للخطيب التبريزي (المنيرية ١٣٥٢هـ)","srcUrl":"https://shamela.ws/book/37488/307","note":"النص برواية التبريزي وترتيبه وضبطه (٥٠ بيتًا) وزيد عليه بيت «إلا مقالة أقوام شقيت بها» من شرح المعلقات التسع والديوان، وقوبل كلمةً كلمةً بسكربت بشرح المعلقات التسع ونص الموسوعة الشعرية وويكي مصدر؛ صُحّحت أخطاء الطباعة في الشكل وأُكمل الناقص من الشواهد، وفُحص وزن كل شطر على البسيط. التفاصيل في تقرير المصادر.","verses":[["يَا دَارَ مَيَّةَ بِالْعَلْيَاءِ فَالسَّنَدِ","أَقْوَتْ وَطَالَ عَلَيْهَا سَالِفُ الْأَبَدِ"],["وَقَفْتُ فِيهَا أَصِيلًا كَيْ أُسَائِلَهَا","عَيَّتْ جَوَابًا وَمَا بِالرَّبْعِ مِنْ أَحَدِ"],["إِلَّا أَوَارِيَّ لَأْيًا مَا أُبَيِّنُهَا","وَالنُّؤْيَ كَالْحَوْضِ بِالْمَظْلُومَةِ الْجَلَدِ"],["رَدَّتْ عَلَيْهِ أَقَاصِيهِ وَلَبَّدَهُ","ضَرْبُ الْوَلِيدَةِ بِالْمِسْحَاةِ فِي الثَّأَدِ"],["خَلَّتْ سَبِيلَ أَتِيٍّ كَانَ يَحْبِسُهُ","وَرَفَّعَتْهُ إِلَى السِّجْفَيْنِ فَالنَّضَدِ"],["أَضْحَتْ خَلَاءً وَأَضْحَى أَهْلُهَا احْتَمَلُوا","أَخْنَى عَلَيْهَا الَّذِي أَخْنَى عَلَى لُبَدِ"],["فَعَدِّ عَمَّا تَرَى إِذْ لَا ارْتِجَاعَ لَهُ","وَانْمِ الْقُتُودَ عَلَى عَيْرَانَةٍ أُجُدِ"],["مَقْذُوفَةٍ بِدَخِيسِ النَّحْضِ بَازِلُهَا","لَهُ صَرِيفٌ صَرِيفَ الْقَعْوِ بِالْمَسَدِ"],["كَأَنَّ رَحْلِي وَقَدْ زَالَ النَّهَارُ بِنَا","بِذِي الْجَلِيلِ عَلَى مُسْتَأْنِسٍ وَحَدِ"],["مِنْ وَحْشِ وَجْرَةَ مَوْشِيٍّ أَكَارِعُهُ","طَاوِي الْمَصِيرِ كَسَيْفِ الصَّيْقَلِ الْفَرَدِ"],["سَرَتْ عَلَيْهِ مِنَ الْجَوْزَاءِ سَارِيَةٌ","تُزْجِي الشَّمَالُ عَلَيْهِ جَامِدَ الْبَرَدِ"],["فَارْتَاعَ مِنْ صَوْتِ كَلَّابٍ فَبَاتَ لَهُ","طَوْعُ الشَّوَامِتِ مِنْ خَوْفٍ وَمِنْ صَرَدِ"],["فَبَثَّهُنَّ عَلَيْهِ وَاسْتَمَرَّ بِهِ","صُمْعُ الْكُعُوبِ بَرِيئَاتٌ مِنَ الْحَرَدِ"],["فَهَابَ ضُمْرَانُ مِنْهُ حَيْثُ يُوزِعُهُ","طَعْنُ الْمُعَارِكِ عِنْدَ الْمُحْجَرِ النَّجُدِ"],["شَكَّ الْفَرِيصَةَ بِالْمِدْرَى فَأَنْفَذَهَا","شَكَّ الْمُبَيْطِرِ إِذْ يَشْفِي مِنَ الْعَضَدِ"],["كَأَنَّهُ خَارِجًا مِنْ جَنْبِ صَفْحَتِهِ","سَفُّودُ شَرْبٍ نَسُوهُ عِنْدَ مُفْتَأَدِ"],["فَظَلَّ يَعْجُمُ أَعْلَى الرَّوْقِ مُنْقَبِضًا","فِي حَالِكِ اللَّوْنِ صَدْقٍ غَيْرِ ذِي أَوَدِ"],["لَمَّا رَأَى وَاشِقٌ إِقْعَاصَ صَاحِبِهِ","وَلَا سَبِيلَ إِلَى عَقْلٍ وَلَا قَوَدِ"],["قَالَتْ لَهُ النَّفْسُ إِنِّي لَا أَرَى طَمَعًا","وَإِنَّ مَوْلَاكَ لَمْ يَسْلَمْ وَلَمْ يَصِدِ"],["فَتِلْكَ تُبْلِغُنِي النُّعْمَانَ إِنَّ لَهُ","فَضْلًا عَلَى النَّاسِ فِي الْأَدْنَى وَفِي الْبَعَدِ"],["وَلَا أَرَى فَاعِلًا فِي النَّاسِ يُشْبِهُهُ","وَمَا أُحَاشِي مِنَ الْأَقْوَامِ مِنْ أَحَدِ"],["إِلَّا سُلَيْمَانَ إِذْ قَالَ الْإِلَهُ لَهُ","قُمْ فِي الْبَرِيَّةِ فَاحْدُدْهَا عَنِ الْفَنَدِ"],["وَخَيِّسِ الْجِنَّ إِنِّي قَدْ أَذِنْتُ لَهُمْ","يَبْنُونَ تَدْمُرَ بِالصُّفَّاحِ وَالْعُمُدِ"],["فَمَنْ أَطَاعَ فَأَعْقِبْهُ بِطَاعَتِهِ","كَمَا أَطَاعَكَ وَادْلُلْهُ عَلَى الرَّشَدِ"],["وَمَنْ عَصَاكَ فَعَاقِبْهُ مُعَاقَبَةً","تَنْهَى الظَّلُومَ وَلَا تَقْعُدْ عَلَى ضَمَدِ"],["إِلَّا لِمِثْلِكَ أَوْ مَنْ أَنْتَ سَابِقُهُ","سَبْقَ الْجَوَادِ إِذَا اسْتَوْلَى عَلَى الْأَمَدِ"],["وَاحْكُمْ كَحُكْمِ فَتَاةِ الْحَيِّ إِذْ نَظَرَتْ","إِلَى حَمَامٍ سِرَاعٍ وَارِدِ الثَّمَدِ"],["قَالَتْ أَلَا لَيْتَمَا هَذَا الْحَمَامُ لَنَا","إِلَى حَمَامَتِنَا وَنِصْفُهُ فَقَدِ"],["يَحُفُّهُ جَانِبَا نِيقٍ وَتُتْبِعُهُ","مِثْلَ الزُّجَاجَةِ لَمْ تُكْحَلْ مِنَ الرَّمَدِ"],["فَحَسَّبُوهُ فَأَلْفَوْهُ كَمَا حَسَبَتْ","تِسْعًا وَتِسْعِينَ لَمْ تَنْقُصْ وَلَمْ تَزِدِ"],["فَكَمَّلَتْ مِائَةً فِيهَا حَمَامَتُهَا","وَأَسْرَعَتْ حِسْبَةً فِي ذَلِكَ الْعَدَدِ"],["أَعْطَى لِفَارِهَةٍ حُلْوٍ تَوَابِعُهَا","مِنَ الْمَوَاهِبِ لَا تُعْطَى عَلَى نَكَدِ"],["الْوَاهِبُ الْمِائَةَ الْأَبْكَارَ زَيَّنَهَا","سَعْدَانُ تُوضِحَ فِي أَوْبَارِهَا اللِّبَدِ"],["وَالسَّاحِبَاتِ ذُيُولَ الْمِرْطِ فَنَّقَهَا","بَرْدُ الْهَوَاجِرِ كَالْغِزْلَانِ بِالْجَرَدِ"],["وَالْخَيْلَ تَمْزَعُ غَرْبًا فِي أَعِنَّتِهَا","كَالطَّيْرِ تَنْجُو مِنَ الشُّؤْبُوبِ ذِي الْبَرَدِ"],["وَالْأُدْمَ قَدْ خُيِّسَتْ فُتْلًا مَرَافِقُهَا","مَشْدُودَةً بِرِحَالِ الْحِيرَةِ الْجُدُدِ"],["فَلَا لَعَمْرُ الَّذِي قَدْ زُرْتُهُ حِجَجًا","وَمَا هُرِيقَ عَلَى الْأَنْصَابِ مِنْ جَسَدِ"],["وَالْمُؤْمِنِ الْعَائِذَاتِ الطَّيْرَ يَمْسَحُهَا","رُكْبَانُ مَكَّةَ بَيْنَ الْغَيْلِ وَالسَّنَدِ"],["مَا إِنْ أَتَيْتُ بِشَيْءٍ أَنْتَ تَكْرَهُهُ","إِذًا فَلَا رَفَعَتْ سَوْطِي إِلَيَّ يَدِي"],["إِلَّا مَقَالَةَ أَقْوَامٍ شَقِيتُ بِهَا","كَانَتْ مَقَالَتُهُمْ قَرْعًا عَلَى الْكَبِدِ"],["إِذًا فَعَاقَبَنِي رَبِّي مُعَاقَبَةً","قَرَّتْ بِهَا عَيْنُ مَنْ يَأْتِيكَ بِالْحَسَدِ"],["هَذَا لِأَبْرَأَ مِنْ قَوْلٍ قُذِفْتُ بِهِ","طَارَتْ نَوَافِذُهُ حَرًّا عَلَى كَبِدِي"],["مَهْلًا فِدَاءٌ لَكَ الْأَقْوَامُ كُلُّهُمُ","وَمَا أُثَمِّرُ مِنْ مَالٍ وَمِنْ وَلَدِ"],["لَا تَقْذِفَنِّي بِرُكْنٍ لَا كِفَاءَ لَهُ","وَلَوْ تَأَثَّفَكَ الْأَعْدَاءُ بِالرِّفَدِ"],["فَمَا الْفُرَاتُ إِذَا جَاشَتْ غَوَارِبُهُ","تَرْمِي أَوَاذِيُّهُ الْعَبْرَيْنِ بِالزَّبَدِ"],["يَمُدُّهُ كُلُّ وَادٍ مُزْبِدٍ لَجِبٍ","فِيهِ حُطَامٌ مِنَ الْيَنْبُوتِ وَالْخَضَدِ"],["يَظَلُّ مِنْ خَوْفِهِ الْمَلَّاحُ مُعْتَصِمًا","بِالْخَيْزُرَانَةِ بَعْدَ الْأَيْنِ وَالنَّجَدِ"],["يَوْمًا بِأَجْوَدَ مِنْهُ سَيْبَ نَافِلَةٍ","وَلَا يَحُولُ عَطَاءُ الْيَوْمِ دُونَ غَدِ"],["أُنْبِئْتُ أَنَّ أَبَا قَابُوسَ أَوْعَدَنِي","وَلَا قَرَارَ عَلَى زَأْرٍ مِنَ الْأَسَدِ"],["هَذَا الثَّنَاءُ فَإِنْ تَسْمَعْ لِقَائِلِهِ","فَمَا عَرَضْتُ أَبَيْتَ اللَّعْنَ بِالصَّفَدِ"],["هَا إِنَّ تَا عِذْرَةٌ إِلَّا تَكُنْ نَفَعَتْ","فَإِنَّ صَاحِبَهَا قَدْ تَاهَ فِي الْبَلَدِ"]],"secs":{"1":"معلقة النابغة الذبياني"}}],"sharh":false};
